def minCostWalkAll(n: int, edges: list[list[int]]) -> int:
    import heapq
    # All-pairs shortest paths via Floyd-Warshall
    dist = [[float('inf')] * n for _ in range(n)]
    for i in range(n): dist[i][i] = 0
    for u, v, w in edges:
        dist[u][v] = min(dist[u][v], w)
        dist[v][u] = min(dist[v][u], w)
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]
    # Check if all nodes reachable from 0
    if any(dist[0][i] == float('inf') for i in range(n)):
        return -1
    # TSP over metric completion starting from 0
    memo = {}
    target = (1 << n) - 1
    def tsp(u, mask):
        if mask == target: return 0
        if (u, mask) in memo: return memo[(u, mask)]
        res = float('inf')
        for v in range(n):
            if not (mask & (1 << v)):
                res = min(res, dist[u][v] + tsp(v, mask | (1 << v)))
        memo[(u, mask)] = res
        return res
    return tsp(0, 1)

